#include <iostream>
#include <vector>
#include <queue>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<vector<int>> adj(n + 1);
    for (int i = 1; i <= n; ++i) {
        int m;
        cin >> m;
        adj[i].resize(m);
        for (int j = 0; j < m; ++j) {
            cin >> adj[i][j];
        }
    }

    vector<int> team(n + 1, 0);
    queue<int> q;

    // O aluno 1 sempre fica no time 1
    team[1] = 1;
    q.push(1);

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (int v : adj[u]) {
            if (team[v] == 0) {
                team[v] = (team[u] == 1 ? 2 : 1);
                q.push(v);
            }
        }
    }

    // Caso existam outras componentes conexas (por segurança)
    for (int i = 1; i <= n; ++i) {
        if (team[i] == 0) {
            team[i] = 1;
            q.push(i);
            while (!q.empty()) {
                int u = q.front();
                q.pop();

                for (int v : adj[u]) {
                    if (team[v] == 0) {
                        team[v] = (team[u] == 1 ? 2 : 1);
                        q.push(v);
                    }
                }
            }
        }
    }

    vector<int> team1, team2;
    for (int i = 1; i <= n; ++i) {
        if (team[i] == 1) {
            team1.push_back(i);
        } else {
            team2.push_back(i);
        }
    }

    for (size_t i = 0; i < team1.size(); ++i) {
        cout << team1[i] << (i + 1 == team1.size() ? "" : " ");
    }
    cout << "\n";

    for (size_t i = 0; i < team2.size(); ++i) {
        cout << team2[i] << (i + 1 == team2.size() ? "" : " ");
    }
    cout << "\n";

    return 0;
}
